<?php
require_once '../config/database.php';
require_once '../config/session.php';
requireLogin();
if (!in_array(getUserRole(), ['teacher','admin'], true)) { http_response_code(403); exit('Forbidden'); }
$db=getDBConnection(); $userId=(int)getUserId(); $examId=(int)($_GET['exam_id']??0);
$sql="SELECT e.id,e.title FROM exams e WHERE e.id=? AND EXISTS (SELECT 1 FROM entrance_exams ee JOIN exam_subjects es ON es.id=ee.exam_subject_id WHERE es.exam_id=e.id".(getUserRole()==='teacher'?' AND ee.teacher_id=?':'').')';
$stmt=$db->prepare($sql); if(getUserRole()==='teacher')$stmt->bind_param('ii',$examId,$userId);else$stmt->bind_param('i',$examId);$stmt->execute();$exam=$stmt->get_result()->fetch_assoc();$stmt->close();
if(!$exam){http_response_code(403);exit('Entrance exam not found or not assigned to you.');}
$sql="SELECT u.full_name,u.email,ea.status,s.name AS subject_name,es.id AS exam_subject_id,a.id AS attempt_id,a.submitted_at,a.score,(SELECT COUNT(*) FROM student_answers sa JOIN questions q ON q.id=sa.question_id WHERE sa.attempt_id=a.id AND q.question_type='theory' AND COALESCE(sa.answer_text,'')<>'' AND sa.marked_at IS NULL) AS pending_theory FROM entrance_applications ea JOIN users u ON u.id=ea.user_id JOIN entrance_exams root_ee ON root_ee.id=ea.entrance_exam_id JOIN exam_subjects root_es ON root_es.id=root_ee.exam_subject_id CROSS JOIN entrance_exams part_ee JOIN exam_subjects es ON es.id=part_ee.exam_subject_id AND es.exam_id=root_es.exam_id JOIN subjects s ON s.id=es.subject_id LEFT JOIN exam_attempts a ON a.id=(SELECT MAX(x.id) FROM exam_attempts x WHERE x.student_id=ea.user_id AND x.exam_subject_id=es.id) WHERE root_es.exam_id=?";
$stmt=$db->prepare($sql);$stmt->bind_param('i',$examId);$stmt->execute();$candidates=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
?>
<?php include '../includes/header.php'; ?>
<style>
.entrance-results{max-width:1250px;color:var(--ink)}.results-hero{padding:1.7rem 2rem;border-radius:12px;background:var(--brand-navy);color:#fff;box-shadow:0 8px 20px rgba(26,36,104,.12)}.results-hero h1{font-weight:750;letter-spacing:-.035em}.results-hero p{color:rgba(255,255,255,.82)}.results-hero .btn{color:#fff;border-color:rgba(255,255,255,.45);border-radius:8px}.entrance-results .card{border:1px solid var(--line);border-radius:12px;box-shadow:0 5px 16px rgba(26,36,104,.05);overflow:hidden}.entrance-results .table{margin:0}.entrance-results .table thead th{padding:.85rem 1rem;background:var(--brand-sky-soft);color:var(--brand-navy-deep);border-bottom:1px solid var(--line);font-size:.72rem;letter-spacing:.06em;text-transform:uppercase}.entrance-results .table td{padding:1rem;border-color:var(--line);vertical-align:middle}.entrance-results .table tbody tr:hover{background:#f7fbfe}.candidate-name{font-weight:700;color:var(--brand-navy-deep)}.candidate-email{font-size:.82rem;color:var(--muted)}.result-score{font-weight:750;font-size:1rem;color:var(--brand-navy)}.result-pending{padding:.42rem .68rem;border-radius:8px;background:#fff4da;color:#805a12;font-size:.78rem;font-weight:700}
</style>
<div class="container py-4 entrance-results"><div class="results-hero d-flex justify-content-between align-items-center gap-3 mb-4"><div><div class="text-uppercase small fw-bold opacity-75 mb-2">Assessment review</div><h1 class="h3 mb-1">Candidate results</h1><p class="mb-0"><?php echo htmlspecialchars($exam['title']); ?> · All subject sections</p></div><a href="entrance_exams.php" class="btn"><i class="fas fa-arrow-left me-2"></i>Entrance exams</a></div><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Candidate</th><th>Subject</th><th>Application</th><th>Submitted</th><th>Score</th><th>Action</th></tr></thead><tbody><?php foreach($candidates as $row): ?><tr><td><div class="candidate-name"><?php echo htmlspecialchars($row['full_name']); ?></div><div class="candidate-email"><?php echo htmlspecialchars($row['email']); ?></div></td><td><?php echo htmlspecialchars($row['subject_name']); ?></td><td><?php echo htmlspecialchars(ucfirst($row['status'])); ?></td><td><?php echo $row['submitted_at']?htmlspecialchars(date('M j, Y H:i',strtotime($row['submitted_at']))):'Not submitted'; ?></td><td><?php if($row['score']===null): ?><span class="result-pending"><?php echo $row['attempt_id']?'Marking pending':'Not attempted'; ?></span><?php else: ?><span class="result-score"><?php echo htmlspecialchars((string)$row['score']); ?></span><?php endif; ?><?php if((int)$row['pending_theory']>0): ?><span class="badge bg-warning text-dark ms-2">Theory marking needed</span><?php endif; ?></td><td><?php if($row['attempt_id']&&(int)$row['pending_theory']>0): ?><a class="btn btn-sm btn-warning" href="mark_theory.php?attempt_id=<?php echo (int)$row['attempt_id']; ?>">Mark theory</a><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$candidates): ?><tr><td colspan="6" class="text-muted text-center py-5">No candidates assigned to this exam.</td></tr><?php endif; ?></tbody></table></div></div></div>
<?php include '../includes/footer.php'; ?>
